for lang in ['russian','english']:
    result={}
    for key,(name,desc) in ru.items():
        result[key]=name if lang=='russian' else en_names[key]
        if desc:result[key+'_desc']=desc if lang=='russian' else en_desc.get(key,en_names[key]+'. Establish the institutions and guarantees of this political settlement.')
    for eid,(title,desc,option) in (ev if lang=='russian' else en_events).items():
        for suffix,val in [('t',title),('d',desc),('a',option)]:result[f'A01_future.{eid}.{suffix}']=val
    result['A01_future.5.b']='Передать власть Совету и арестовать Людольфа.' if lang=='russian' else 'Transfer power to the council and imprison Ludolf.'
    result['A01_future.16.b']='Продолжить спор без вмешательства короны.' if lang=='russian' else 'Continue the contest without the crown.'
    # Update existing keys in their original files, preventing duplicate localisation.
    update_values = dict(result)
    update_values.update(overrides if lang=='russian' else en_overrides)
    output_path=R/f'localisation/{lang}/zzzz_postwar_future_l_{lang}.yml'
    for key,val in update_values.items():
        found=False
        for p in (R/'localisation'/lang).glob('*.yml'):
            if p==output_path: continue
            s=p.read_text(encoding='utf-8-sig')
            pattern=r'^\s+'+re.escape(key)+r':(?:\d+)? .*?$'
            s,n=re.subn(pattern,lambda m:f' {key}:0 "{val.replace(chr(10),r"\n")}"',s,flags=re.M)
            if n:p.write_text(s,encoding='utf-8-sig');found=True
        if not found:result[key]=val
        else:result.pop(key,None)
    s=f'l_{lang}:\n'
    for key,val in result.items():s+=f' {key}:0 "{val.replace(chr(10),r"\n")}"\n'
    (R/f'localisation/{lang}/zzzz_postwar_future_l_{lang}.yml').write_text(s,encoding='utf-8-sig')
print('Russian narrative and matching English localisation written.')
